class Account {
    protected long balance;
    Account(long b) { this.balance = b; }
    void deposit(long x) { balance += x; }
}
class Savings extends Account {
    private double rate;
    Savings(long b, double r) { super(b); this.rate = r; }   // call the superclass constructor
    void addInterest() { balance += (long)(balance * rate); } // protected member is visible
}
